function initClock(){state.clock??={};state.clock.speed=[1,2,3].includes(state.clock.speed)?state.clock.speed:1;state.clock.paused=state.clock.paused===true;if(state.clock.mapTarget&&(!Number.isFinite(state.clock.mapTarget.x)||!Number.isFinite(state.clock.mapTarget.y)))delete state.clock.mapTarget}
function setGameSpeed(speed){if(![1,2,3].includes(speed))return false;state.clock.speed=speed;renderClock();save();return true}
function togglePause(){state.clock.paused=!state.clock.paused;keys={};renderClock();save();return state.clock.paused}
function renderClock(){const paused=state.clock.paused;$('pauseGame').textContent=paused?'▶ Wznów':'Ⅱ Pauza';$('atlasPause').textContent=paused?'▶ Wznów':'Ⅱ Pauza';$('clockStatus').textContent=paused?'PAUZA':'Tempo ×'+state.clock.speed;for(const b of document.querySelectorAll('[data-game-speed]')){b.classList.toggle('active',Number(b.dataset.gameSpeed)===state.clock.speed);b.setAttribute?.('aria-pressed',Number(b.dataset.gameSpeed)===state.clock.speed?'true':'false')} $('pauseGame').classList.toggle('active',paused);$('atlasClock').textContent=paused?'Świat zatrzymany':'Czas płynie · ×'+state.clock.speed}
let atlasOpen=false,atlasSelected=null,atlasSearch='',atlasLastDraw=-Infinity,atlasTerrainSignature='',atlasListSignature='',atlasFocusBefore=null;
const atlasTerrain=document.createElement('canvas');atlasTerrain.width=N;atlasTerrain.height=N;const atc=atlasTerrain.getContext('2d');
function atlasIsOpen(){return atlasOpen}
function openAtlas(){atlasOpen=true;atlasLastDraw=-Infinity;atlasFocusBefore=document.activeElement;keys={};target=null;if(typeof cancelSelectionDrag==='function')cancelSelectionDrag();$('worldMap').classList.remove('hidden');$('atlasClose').focus?.();renderClock();renderAtlas(true)}
function closeAtlas(){atlasOpen=false;keys={};$('worldMap').classList.add('hidden');atlasFocusBefore?.focus?.()}
function relationName(t){return {scouting:'Wysyła zwiad',neutral:'Pokój',war:'Wojna',allied:'Sojusz',conquered:'Twoja osada'}[t.relation]||'Osada'}
function atlasEntities(){const out=[],w=state.war;
 for(const u of w.guards||[])out.push({id:'guard:'+u.uid,type:'guard',label:u.kind==='cavalry'?'Jeździec':u.kind==='crossbow'?'Kusznik':u.kind==='shield'?'Tarczownik':u.kind==='archer'?'Łucznik':'Żołnierz',x:u.x/T,y:u.y/T,color:'#a9d5e5',unit:u,route:u.path?.map(p=>({x:p.x/T,y:p.y/T}))||[]});
 for(const p of w.patrols||[])for(let i=0;i<p.units.length;i++){const u=p.units[i];out.push({id:'patrol:'+p.id+':'+i,type:'patrol',label:'Patrol · '+p.units.length,x:u.x/T,y:u.y/T,color:'#84b9c3',unit:u,route:[p.a,p.b]})}
 for(const u of w.engines||[])out.push({id:'engine:'+u.uid,type:'engine',label:ENGINE_TYPES[u.kind].name,x:u.x/T,y:u.y/T,color:'#d8b775',unit:u,route:u.path?.map(p=>({x:p.x/T,y:p.y/T}))||[]});
 if(w.expedition){const p=routePosition(w.expedition);out.push({id:'expedition',type:'expedition',label:'Wyprawa · '+w.expedition.troops,x:p.x/T,y:p.y/T,color:'#a9d5e5',route:w.expedition.route})}
 for(const r of w.raids||[]){const p=routePosition(r);if(seen.has(tileKey(Math.floor(p.x/T),Math.floor(p.y/T))))out.push({id:'raid:'+r.townId,type:'raid',label:r.scout?'Zwiadowca orków':'Najazd · '+Math.ceil(r.power),x:p.x/T,y:p.y/T,color:'#ef997c',route:r.route.filter(q=>seen.has(tileKey(Math.floor(q.x),Math.floor(q.y))))})}
 for(const a of w.support||[]){const p=a.phase==='march'?routePosition(a):a.units[0];if(p)out.push({id:'support:'+a.townId,type:'support',label:'Pomoc sojusznicza · '+a.troops,x:p.x/T,y:p.y/T,color:'#aed997',route:a.route})}
 for(const s of state.kingdom?.fleet||[])out.push({id:'ship:'+s.id,type:'ship',label:'Statek · desant '+s.passengers.length+'/4',x:s.x/T,y:s.y/T,color:'#86c5dd',route:s.route||[]});
 for(const c of state.kingdom?.caravans||[]){const p=routePosition(c);out.push({id:'caravan:'+c.id,type:'caravan',label:'Karawana · eskorta '+c.escorts.length,x:p.x/T,y:p.y/T,color:'#e0c58d',route:c.route})}for(const m of state.frontier?.marches||[]){const p=routePosition(m);if(seen.has(tileKey(Math.floor(p.x/T),Math.floor(p.y/T))))out.push({id:m.id,type:'neighbor',label:'Wojna sąsiadów · '+Math.ceil(m.power),x:p.x/T,y:p.y/T,color:'#d7ad83',route:m.route.filter(q=>seen.has(tileKey(Math.floor(q.x),Math.floor(q.y))))})}return out;
}
function selectedAtlasItem(){if(!atlasSelected)return null;if(atlasSelected.kind==='town'){const t=state.towns.find(t=>t.id===atlasSelected.id);return t?{kind:'town',town:t,x:t.x,y:t.y,label:t.name}:null}if(atlasSelected.kind==='entity'){const e=atlasEntities().find(e=>e.id===atlasSelected.id);return e?{...e,kind:'entity'}:null}return atlasSelected}
function selectAtlasTown(id){if(!state.towns.some(t=>t.id===id))return false;atlasSelected={kind:'town',id};atlasLastDraw=-Infinity;renderAtlas(true);return true}
function atlasGeometry(width,height){const size=Math.max(1,Math.min(width,height)-24);return {x:(width-size)/2,y:(height-size)/2,size}}
function atlasPoint(clientX,clientY,rect){const g=atlasGeometry(rect.width,rect.height),x=(clientX-rect.left-g.x)/g.size*N,y=(clientY-rect.top-g.y)/g.size*N;if(x<0||y<0||x>=N||y>=N)return null;return {x:Math.floor(x),y:Math.floor(y)}}
function selectAtlasPoint(p,pixelsPerTile=1){const candidates=[...state.towns.map(t=>({kind:'town',id:t.id,x:t.x,y:t.y})),...atlasEntities().map(e=>({kind:'entity',id:e.id,x:e.x,y:e.y}))].map(e=>({...e,d:Math.hypot(e.x-p.x,e.y-p.y)*pixelsPerTile})).filter(e=>e.d<9).sort((a,b)=>a.d-b.d);atlasSelected=candidates[0]||{kind:'point',x:p.x,y:p.y,label:'Wybrany teren'};atlasLastDraw=-Infinity;renderAtlas(true)}
function atlasWaypoint(){const item=selectedAtlasItem();if(!item)return false;if(item.kind==='town'){state.war.waypoint=item.town.id;delete state.clock.mapTarget}else{state.war.waypoint=null;state.clock.mapTarget={x:Math.floor(item.x),y:Math.floor(item.y)}}warPanelSignature='';save();ui();closeAtlas();say('Wyznaczono kierunek: '+(item.label||'teren')+'.');return true}
function atlasSelectUnit(){const item=selectedAtlasItem();if(!item?.unit||!['guard','engine'].includes(item.type))return false;toggleUnitSelection(item.unit,false);closeAtlas();return true}
function atlasMoveSelected(){const item=selectedAtlasItem();if(!item||!selectedActors().length)return false;const prior=commandDraft;commandDraft='move';const ok=issueMapCommand(Math.floor(item.x),Math.floor(item.y));if(ok)closeAtlas();else commandDraft=prior;return ok}
function drawAtlasTerrain(){const signature=(state.fullMap?'full':seen.size)+':'+state.buildings.length+':'+floodedTrenches.size+':'+(typeof seasonIndex==='function'?seasonIndex():0);if(signature===atlasTerrainSignature)return;atlasTerrainSignature=signature;atc.fillStyle='#183329';atc.fillRect(0,0,N,N);for(const key of mapVisionTiles()){const [x,y]=key.split(',').map(Number),t=terrain(x,y);atc.fillStyle=t==='water'?'#639ea3':t==='ravine'?'#63574b':t==='sand'?'#b3ad7d':(typeof seasonInfo==='function'?seasonInfo().color:'#809466');atc.fillRect(x,y,state.fullMap?2:1,state.fullMap?2:1)}}
function atlasRoute(ctx,route,g,color,dashed=false){if(!route?.length)return;ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.setLineDash(dashed?[4,4]:[]);ctx.beginPath();for(let i=0;i<route.length;i++){const p=route[i],x=g.x+p.x/N*g.size,y=g.y+p.y/N*g.size;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();ctx.setLineDash([])}
function drawAtlas(){const canvas=$('atlasCanvas'),rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=devicePixelRatio||1,W=rect.width,H=rect.height;const width=Math.round(W*dpr),height=Math.round(H*dpr);if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height}const ac=canvas.getContext('2d');ac.setTransform(dpr,0,0,dpr,0,0);ac.fillStyle='#102820';ac.fillRect(0,0,W,H);const g=atlasGeometry(W,H);drawAtlasTerrain();ac.imageSmoothingEnabled=false;ac.drawImage(atlasTerrain,g.x,g.y,g.size,g.size);ac.strokeStyle='#c9b57566';ac.strokeRect(g.x,g.y,g.size,g.size);
 ac.strokeStyle='#d3cf9433';ac.lineWidth=1;for(let n=0;n<=N;n+=80){const p=n/N*g.size;ac.beginPath();ac.moveTo(g.x+p,g.y);ac.lineTo(g.x+p,g.y+g.size);ac.moveTo(g.x,g.y+p);ac.lineTo(g.x+g.size,g.y+p);ac.stroke()}
 for(const t of state.towns.filter(t=>t.relation==='conquered')){ac.fillStyle='#b7d39122';ac.beginPath();ac.arc(g.x+t.x/N*g.size,g.y+t.y/N*g.size,8/N*g.size,0,7);ac.fill()}
 const entities=atlasEntities(),selected=selectedAtlasItem();for(const e of entities)atlasRoute(ac,e.route,g,e.type==='raid'?'#ec927b44':'#afc8a233',true);if(selected?.kind==='entity')atlasRoute(ac,selected.route,g,'#f4db8c');
 for(const t of state.towns){const x=g.x+t.x/N*g.size,y=g.y+t.y/N*g.size;ac.fillStyle=!t.discovered?'#899b7c':t.relation==='war'?'#e58e75':t.relation==='allied'?'#a6d294':t.relation==='conquered'?'#88bfd0':t.color;ac.fillRect(x-2.5,y-2.5,5,5)}
 for(const e of entities){ac.fillStyle=e.color;ac.beginPath();ac.arc(g.x+e.x/N*g.size,g.y+e.y/N*g.size,3,0,7);ac.fill()}
 const o=villageOrigin();if(state.settled){ac.strokeStyle='#e4c983';ac.lineWidth=2;ac.strokeRect(g.x+o.x/N*g.size-5,g.y+o.y/N*g.size-5,10,10)}ac.fillStyle='#ffe49a';ac.beginPath();ac.arc(g.x+state.p.x/T/N*g.size,g.y+state.p.y/T/N*g.size,4,0,7);ac.fill();if(selected){ac.strokeStyle='#fff0b9';ac.lineWidth=2;ac.beginPath();ac.arc(g.x+selected.x/N*g.size,g.y+selected.y/N*g.size,9,0,7);ac.stroke()}ac.fillStyle='#e3ce94';ac.font='11px system-ui';ac.fillText('N ↑',g.x+g.size-29,g.y+16);
}
function renderAtlasSelection(){const item=selectedAtlasItem();if(!item){$('atlasSelection').innerHTML='<h3>Wybierz cel</h3><p>Kliknij osadę, wojsko lub teren. Wybór celu nie przenosi ludka.</p>';$('atlasWaypoint').disabled=true;$('atlasSelectUnit').disabled=true;$('atlasMove').disabled=true;return}$('atlasWaypoint').disabled=false;$('atlasSelectUnit').disabled=!(item.kind==='entity'&&['guard','engine'].includes(item.type));$('atlasMove').disabled=!selectedActors().length||!seen.has(tileKey(Math.floor(item.x),Math.floor(item.y)));$('atlasSelection').innerHTML=`<h3>${item.label}</h3><p>${Math.floor(item.x)}, ${Math.floor(item.y)}${item.kind==='town'?' · '+(item.town.discovered?relationName(item.town):'Pogłoski')+(item.town.discovered?' · obrona '+item.town.power:''):item.kind==='entity'?' · '+(item.unit?.hp!==undefined?Math.ceil(item.unit.hp)+' PŻ':'oddział w drodze'):''}</p><p>${item.kind==='entity'?'Trasa oddziału jest wyróżniona na mapie.':item.kind==='town'&&!item.town.discovered?'Podejdź bliżej, aby odkryć osadę.':'Wskaż kierunek lub wyślij zaznaczoną grupę.'}</p>`}
function renderAtlasList(){const towns=state.towns.filter(t=>!atlasSearch||t.name.toLocaleLowerCase('pl').includes(atlasSearch.toLocaleLowerCase('pl'))),sig=JSON.stringify([atlasSearch,atlasSelected?.id,towns.map(t=>[t.id,t.relation,t.discovered])]);if(sig===atlasListSignature)return;atlasListSignature=sig;$('atlasTownCount').textContent=towns.length+' / '+state.towns.length+' osad';$('atlasTownList').innerHTML=towns.map(t=>`<button data-atlas-town="${t.id}" class="${atlasSelected?.kind==='town'&&atlasSelected.id===t.id?'active':''}"><span>${t.name}</span><small>${t.x}, ${t.y} · ${t.discovered?relationName(t):'Pogłoski'}</small></button>`).join('')||'<p>Brak osad o tej nazwie.</p>'}
function renderAtlas(force=false){if(!atlasOpen)return;const now=performance.now();if(!force&&now-atlasLastDraw<250)return;atlasLastDraw=now;renderClock();drawAtlas();renderAtlasSelection();renderAtlasList()}
function drawAtlasTarget(){const t=state.clock?.mapTarget;if(!t)return;const dx=(t.x+.5)*T-state.p.x,dy=(t.y+.5)*T-state.p.y,a=Math.atan2(dy,dx),x=state.p.x+Math.cos(a)*95,y=state.p.y+Math.sin(a)*95;ctx.save();ctx.translate(x,y);ctx.rotate(a);polygon([[13,0],[-7,-7],[-3,0],[-7,7]],'#f0cc77');ctx.restore();ctx.fillStyle='#f6e4b8';ctx.font='11px system-ui';ctx.fillText('Cel '+t.x+', '+t.y+' · '+Math.round(Math.hypot(dx,dy)/T)+' pól',x+14,y-7)}
$('atlasOpen').onclick=openAtlas;$('atlasClose').onclick=closeAtlas;$('pauseGame').onclick=togglePause;$('atlasPause').onclick=togglePause;$('clockControls').onclick=e=>{const b=e.target.closest('button[data-game-speed]');if(b)setGameSpeed(Number(b.dataset.gameSpeed))};$('atlasSpeeds').onclick=e=>{const b=e.target.closest('button[data-game-speed]');if(b)setGameSpeed(Number(b.dataset.gameSpeed))};$('atlasWaypoint').onclick=atlasWaypoint;$('atlasSelectUnit').onclick=atlasSelectUnit;$('atlasMove').onclick=atlasMoveSelected;$('atlasSearch').oninput=e=>{atlasSearch=e.target.value;renderAtlas(true)};$('atlasTownList').onclick=e=>{const b=e.target.closest('button[data-atlas-town]');if(b)selectAtlasTown(b.dataset.atlasTown)};$('atlasCanvas').onclick=e=>{const rect=$('atlasCanvas').getBoundingClientRect(),p=atlasPoint(e.clientX,e.clientY,rect);if(p)selectAtlasPoint(p,atlasGeometry(rect.width,rect.height).size/N)};
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)||e.target?.isContentEditable)return;if(e.repeat)return;if(e.key===' '){e.preventDefault();togglePause()}if(e.key.toLowerCase()==='m'){e.preventDefault();atlasOpen?closeAtlas():openAtlas()}if(e.key==='Escape'&&atlasOpen)closeAtlas()});
